        "shape": [
            "kind": "rect", "width": 1920, "height": 1080,
            "fill": [0.5, 0.5, 0.5, 1.0],
        ] as [String: Any],
    ]
}

func project(tracks: [[String: Any]], clips: [[String: Any]], nests: [[String: Any]])
    -> [String: Any] {
