        "version": 2,
        "canvas": [
            "width": 1920, "height": 1080, "fps": [30, 1],
            "background": [0.0, 0.0, 0.0, 1.0],
            "fit_new_clips": true, "timecode_frames": true,
        ] as [String: Any],
        "media": [] as [Any], "tracks": tracks, "clips": clips, "markers": [] as [Any],
        "next_id": 20, "nests": nests,
    ]
}

