        print(name, "no recipe")
        return
    }
    let boxes = CanvasLayerBox.boxes(recipe: recipe, snapshot: snapshot)
    let degraded = CanvasLayerBox.boxes(snapshot: snapshot, at: 600_000)
    print(name)
    print("  snapshot top-level clips:", snapshot.clips.map(\.id))
    print("  recipe layer clip ids:   ", recipe.layers.map(\.clip))
    print("  boxes (recipe path):     ", boxes.map(\.id))
    print("  boxes (degraded path):   ", degraded.map(\.id))
}

